public class StringEqualityDemo {
    public static void main(String[] args) {
        String literal1 = "Java";
        String literal2 = "Java";
        String heapString = new String("Java");
        String uppercase = "JAVA";
        String nullString = null;

        // 1. Reference equality (==)
        System.out.println("literal1 == literal2: " + (literal1 == literal2)); // true
        System.out.println("literal1 == heapString: " + (literal1 == heapString)); // false

        // 2. Content equality (.equals)
        System.out.println("literal1.equals(heapString): " + literal1.equals(heapString)); // true
        System.out.println("literal1.equals(uppercase): " + literal1.equals(uppercase)); // false

        // 3. Case-insensitive equality
        System.out.println("literal1.equalsIgnoreCase(uppercase): " + literal1.equalsIgnoreCase(uppercase)); // true

        // 4. Null-Safe comparison pattern
        // nullString.equals("Java"); // Would crash with NullPointerException!
        System.out.println("Null-safe check: " + "Java".equals(nullString)); // false (safe!)
    }
}

