practiceProblems.solutionCode:
public class CorsOriginCheck {
    public static void main(String[] args) {
        String[] allowedOrigins = {"https://app.com", "https://api.com", "http://localhost:3000"};
        String incoming = new String("https://api.com");
        boolean authorized = false;
        for (String origin : allowedOrigins) {
            if (origin.equals(incoming)) {
                authorized = true;
                break;
            }
        }
        System.out.println("Authorized: " + authorized);
    }
}

